function createTrack(){const pts=[[0,0,67],[30,0,61],[52,0,42],[62,0,12],[57,0,-17],[42,0,-42],[16,0,-57],[-16,0,-57],[-43,0,-44],[-60,0,-20],[-63,0,12],[-52,0,41],[-29,0,59]];
trackCurve=new THREE.CatmullRomCurve3(pts.map(p=>new THREE.Vector3(...p)),true,'catmullrom',.38);trackLength=trackCurve.getLength();roadGroup=new THREE.Group();scene.add(roadGroup);
const N=420, width=18, positions=[],uvs=[],indices=[];for(let i=0;i<=N;i++){const t=i/N,p=trackCurve.getPointAt(t),tan=trackCurve.getTangentAt(t),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();p.y+=.35+Math.sin(t*Math.PI*8)*.25;for(const x of [-width/2,width/2]){positions.push(p.x+side.x*x,p.y,p.z+side.z*x);uvs.push(i/N*24,(x+width/2)/width)}}for(let i=0;i<N;i++){const a=i*2;indices.push(a,a+1,a+2,a+1,a+3,a+2)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));geo.setIndex(indices);geo.computeVertexNormals();const road=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0x333a3a,roughness:.96,side:THREE.DoubleSide}));road.receiveShadow=true;roadGroup.add(road);
// edge lines and rumble strips
for(const edge of [-1,1]){const epos=[];for(let i=0;i<=N;i++){const t=i/N,p=trackCurve.getPointAt(t),tan=trackCurve.getTangentAt(t),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();p.y+=.42+Math.sin(t*Math.PI*8)*.25;epos.push(p.x+side.x*edge*8.6,p.y+.04,p.z+side.z*edge*8.6,p.x+side.x*edge*9.1,p.y+.04,p.z+side.z*edge*9.1)}const eg=new THREE.BufferGeometry();eg.setAttribute('position',new THREE.Float32BufferAttribute(epos,3));let ei=[];for(let i=0;i<N;i++)ei.push(i*2,i*2+1,i*2+2,i*2+1,i*2+3,i*2+2);eg.setIndex(ei);const em=new THREE.Mesh(eg,new THREE.MeshBasicMaterial({color:0xe9e9dc,side:THREE.DoubleSide}));roadGroup.add(em)}
// Kerb blocks alternate red/ivory along both edges
for(let i=0;i<140;i++){const t=i/140,p=trackCurve.getPointAt(t),tan=trackCurve.getTangentAt(t),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();for(const e of [-1,1]){const b=new THREE.Mesh(new THREE.BoxGeometry(.8,.19,1.35),mat(i%2?0xe9e9dd:0xe65a52));b.position.set(p.x+side.x*e*9.15,p.y+.38,p.z+side.z*e*9.15);b.rotation.y=Math.atan2(tan.x,tan.z);roadGroup.add(b)}}
// start/finish line checkers across width
const sp=trackCurve.getPointAt(0),st=trackCurve.getTangentAt(0),ss=new THREE.Vector3(st.z,0,-st.x).normalize();for(let i=0;i<18;i++){const tile=new THREE.Mesh(new THREE.BoxGeometry(1,.045,.65),mat(i%2?0xf0f0e5:0x141b1a));tile.position.set(sp.x+ss.x*(i-8.5),sp.y+.48,sp.z+ss.z*(i-8.5));tile.rotation.y=Math.atan2(st.x,st.z);roadGroup.add(tile)}
// luminous checkpoint arches
for(const t of [.18,.43,.68,.9]){const p=trackCurve.getPointAt(t),tan=trackCurve.getTangentAt(t),rot=Math.atan2(tan.x,tan.z),g=new THREE.Group();g.position.set(p.x,p.y+.45,p.z);g.rotation.y=rot;const glow=new THREE.MeshBasicMaterial({color:0xd8ff3e});for(const x of [-8.7,8.7]){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.13,.13,4.7,8),glow);pole.position.set(x,2.35,0);g.add(pole)}const beam=new THREE.Mesh(new THREE.BoxGeometry(17.5,.18,.22),glow);beam.position.y=4.7;g.add(beam);const ring=new THREE.Mesh(new THREE.TorusGeometry(8.7,0.12,5,40,Math.PI),new THREE.MeshBasicMaterial({color:0x61e5e8}));ring.position.y=2.3;ring.rotation.z=Math.PI;g.add(ring);scene.add(g);gates.push({t,group:g,used:false})}
// roadside safety barriers and flags
for(let i=0;i<82;i++){const t=i/82,p=trackCurve.getPointAt(t),tan=trackCurve.getTangentAt(t),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();for(const e of [-1,1]){if(i%2)continue;const b=addBox(scene,'barrier',[p.x+side.x*e*11,.52,p.z+side.z*e*11],[2.5,1.05,.5],mat(i%4===0?0xe4e5db:0x53716a));b.rotation.y=Math.atan2(tan.x,tan.z)}}
}
function pointOn(t,lateral=0){const p=trackCurve.getPointAt(((t%1)+1)%1),tan=trackCurve.getTangentAt(((t%1)+1)%1),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();return {p:p.addScaledVector(side,lateral),tan,side};}

